import{Ct as e,Q as t,rt as n,t as r,tt as i}from"./chunks/framework.Bol8dOGv.js";var a=JSON.parse(`{"title":"Search Worker","description":"","frontmatter":{"title":"Search Worker","order":6},"headers":[],"relativePath":"services/search-worker/index.md","filePath":"services/search-worker/index.md"}`),o={name:`services/search-worker/index.md`};function s(r,a,o,s,c,l){return e(),i(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...a[0]||=[n(`<h1 id="search-worker" tabindex="-1">Search Worker <a class="header-anchor" href="#search-worker" aria-label="Permalink to “Search Worker”">​</a></h1><p>NestJS worker consuming integration events from Redpanda and syncing notes into Meilisearch.</p><ul><li><a href="./flows.html">Flows</a>: indexing, deletion races, and readiness.</li><li><a href="./../note/">Note service</a> owns note metadata and search-token authorization; <a href="./../document/">Document service</a> owns editable content.</li></ul><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><table tabindex="0"><thead><tr><th>Event topic</th><th>Index effect</th></tr></thead><tbody><tr><td><code>events.integration.note.note.created</code></td><td>Upsert note ID, name, and workspace ID.</td></tr><tr><td><code>events.integration.note.note.updated</code></td><td>Upsert name, folder ID and name, and trashed state.</td></tr><tr><td><code>events.integration.document.document.committed</code></td><td>Convert BlockNote blocks to lossy Markdown and upsert content and tags.</td></tr><tr><td><code>events.integration.note.note.deleted</code></td><td>Mark a tombstone and delete the note from the index.</td></tr></tbody></table><p>Updates are partial and can arrive independently: metadata and committed content populate the same <code>notes</code> document by ID. Indexing is asynchronous; uncommitted edits are not indexed. The worker does not serve search requests. The note service checks workspace read permission before issuing a scoped Meilisearch tenant token.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h2><ul><li>Run <code>nx run search-worker:seed</code> in every environment to configure the <code>notes</code> index (primary key <code>id</code>), searchable fields (<code>name</code>, <code>folderName</code>, <code>plainTextContent</code>, <code>tags</code>), filters (<code>workspaceId</code>, <code>tags</code>), name sorting, and a search-only key. Set <code>NOTOPIA_SEARCH_WORKER_MEILI_HOST</code>, <code>NOTOPIA_SEARCH_WORKER_MEILI_API_KEY</code>, and <code>NOTOPIA_SEARCH_WORKER_MEILI_NOTE_SEARCH_KEY_UID</code>; the UID must match <code>NOTOPIA_NOTE_MEILISEARCH_NOTE_SEARCH_KEY_UID</code>. A newly created key is printed only outside production.</li><li>Development fixtures are separate from seed: run <code>nx run search-worker:fixtures:transform</code> before <code>nx run search-worker:fixtures</code>.</li><li>HTTP health endpoints <code>/search-worker/health/live</code> and <code>/search-worker/health/ready</code> listen on <code>NOTOPIA_SEARCH_WORKER_HEALTH_CHECK_PORT</code> (default <code>28083</code>). Readiness requires both Meilisearch health and a recent Kafka group join or heartbeat.</li><li>Set <code>NOTOPIA_SEARCH_WORKER_REDIS_URL</code> for shared deletion tombstones across instances. Without it, the worker warns and uses a single-instance in-memory LRU cache. Tombstones expire after <code>NOTOPIA_SEARCH_WORKER_TOMBSTONE_TTL_SECONDS</code> (default <code>86400</code>); choose a TTL longer than worst-case consumer lag plus retries. <code>NOTOPIA_SEARCH_WORKER_TOMBSTONE_MAX</code> bounds the in-memory cache, so eviction can also end protection early.</li></ul><p>Meilisearch write tasks are awaited and unsuccessful tasks are reported as errors. The source contains a retry exception filter, but it is not registered by the worker; do not assume its retry or offset policy is active.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2>`,10),t(`figure`,{class:`vpd-diagram vpd-diagram--d2`,onclick:`
        const figure = this;
        const isFullscreen = figure.classList.contains('vpd-diagram--fullscreen');

        document.querySelectorAll('.vpd-diagram').forEach(diagram => {
          diagram.classList.remove('vpd-diagram--fullscreen');
        });

        if (!isFullscreen) {
          figure.classList.add('vpd-diagram--fullscreen');
        }
      `},[t(`img`,{src:`/notopia/pr/287/diagrams/d2-architecture-search-worker-diagram-4f30b74a4fc1b540f5465d7b5a1f7f4e.svg`,alt:`d2 Diagram`,class:`vpd-diagram-image`})],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};